14	pub(crate) struct SelectionTab {
15	    pub(crate) id: String,
16	    pub(crate) label: String,
17	    pub(crate) header: Box<dyn Renderable>,
18	    pub(crate) items: Vec<SelectionItem>,
19	}
20	
21	pub(crate) fn tab_bar_height(tabs: &[SelectionTab], active_idx: usize, width: u16) -> u16 {
22	    if tabs.is_empty() {
23	        return 0;
24	    }
25	    tab_bar_lines(tabs, active_idx, width)
26	        .len()
27	        .try_into()
28	        .unwrap_or(u16::MAX)
29	}
