fn is_curated_marketplace(marketplace: &PluginMarketplaceEntry) -> bool {
    marketplace.name == OPENAI_CURATED_MARKETPLACE_NAME
}

/// The label shown on a marketplace's tab. The OpenAI curated marketplace is
/// always labeled "OpenAI Curated"; other marketplaces use their display name.
fn marketplace_tab_label(marketplace: &PluginMarketplaceEntry) -> String {
    if is_curated_marketplace(marketplace) {
        "OpenAI Curated".to_string()
    } else {
        marketplace_display_name(marketplace)
    }
}

/// A stable, unique tab ID derived from the marketplace's filesystem path so
/// tabs that share a display name can still be addressed individually.
fn marketplace_tab_id(marketplace: &PluginMarketplaceEntry) -> String {
    format!(
        "{PLUGINS_MARKETPLACE_TAB_PREFIX}{}",
        marketplace.path.to_string_lossy()
    )
}

fn push_remote_sync_error(header: &mut ColumnRenderable, remote_sync_error: Option<&str>) {
    if let Some(remote_sync_error) = remote_sync_error {
        header.push(Line::from(
            format!("Using cached marketplace data: {remote_sync_error}").dim(),
        ));
    }
}

fn plugins_items_or_placeholder(
    items: Vec<SelectionItem>,
    empty_name: &str,
    empty_description: &str,
) -> Vec<SelectionItem> {
    if items.is_empty() {
        vec![SelectionItem {
            name: empty_name.to_string(),
            description: Some(empty_description.to_string()),
            is_disabled: true,
            ..Default::default()
        }]
    } else {
        items
    }
}

/// Flatten and sort every plugin across the given marketplaces: installed
/// plugins first, then case-insensitively by display name.
fn plugin_entries_sorted<'a>(
    marketplaces: &[&'a PluginMarketplaceEntry],
) -> Vec<(&'a PluginMarketplaceEntry, &'a PluginSummary, String)> {
